import std.concurrent as conc
import std.io

pub type AppError = Failed(String)

pub fn main() effect io -> Result<(), AppError> {
    let ch: conc.Channel<Int64> = conc.channel(0)
    scope {
        let p1 = task effect io {
            io.println("p1a")
            ch.send(1)
            io.println("p1b")
        }
        let c1 = task effect io {
            let v = ch.receive()
            io.println("c1a")
            io.println("c1b")
        }
        let _ = p1.await()
        let _ = c1.await()
    }
    return Ok(())
}
